func TestExportUpstreamLineageNoUpstreams(t *testing.T) {
	graph := buildRegisteredGraph(t, [][]string{
		{"root"},
		{"other"},
	})

	out := mustExport(t, graph, "root")
	if want := `{"nodes":["root"],"edges":[]}`; out != want {
