167			}
168		}
169	
170		// The old name leaves the document entirely: no raw illegal byte and no
171		// node decoded back to it. Unrelated nodes never enter report's closure.
172		if strings.Contains(out, "\xff") {
173			t.Errorf("illegal byte from the old name leaked into the export: %s", out)
174		}
175		for _, name := range doc.Nodes {
176			if name == repairBadName {
177				t.Errorf("old invalid name decoded back from the export: %q", name)
178			}
179		}
180		for _, excluded := range []string{"side", "stranger"} {
181			if strings.Contains(out, excluded) {
182				t.Errorf("node outside report's derivation (%q) leaked into the export: %s", excluded, out)
183			}
184		}
185	
186		// The repaired export must be byte-identical to that of an always-valid
187		// twin lineage holding the same relationships: the repair changed names
188		// only, never the node or dependency set.
189		twin := buildRegisteredGraph(t, [][]string{
190			{"src"},
191			{"repaired", "src"},
192			{"merge", "src", "repaired"},
193			{"report", "merge"},
194			{"side", "repaired"},
